// Complete Bilingual Riddle Database - 1000 Unique Riddles
// Telugu & English with difficulty progression

export interface Riddle {
  id: number;
  telugu: string;
  english: string;
  answer: string[];
  hint: string;
  difficulty: 'easy' | 'medium' | 'hard' | 'expert' | 'genius';
}

// Helper to get difficulty based on level
export const getDifficulty = (level: number): Riddle['difficulty'] => {
  if (level <= 100) return 'easy';
  if (level <= 250) return 'medium';
  if (level <= 400) return 'hard';
  if (level <= 600) return 'hard';
  if (level <= 800) return 'expert';
  return 'genius';
};

// Check if level is premium
export const isPremiumLevel = (level: number): boolean => level > 400;

