// Get riddle by level
export const getRiddle = (level: number): Riddle => {
  const riddle = riddlesData.find(r => r.id === level);
  if (!riddle) {
    // Fallback for any missing levels
    return {
      id: level,
      telugu: `స్థాయి ${level} పొడుపు కథ: జ్ఞానం అన్వేషణలో ఉంది. అది ఏమిటి?`,
      english: `Level ${level} riddle: Wisdom lies in the search. What is it?`,
      answer: ["knowledge", "జ్ఞానం", "wisdom"],
      hint: "Think deeply",
      difficulty: getDifficulty(level)
    };
  }
  return riddle;
};

// Get all riddles for a difficulty
export const getRiddlesByDifficulty = (difficulty: Riddle['difficulty']): Riddle[] => {
  return riddlesData.filter(r => r.difficulty === difficulty);
};

// Total riddle count
export const getTotalRiddleCount = (): number => riddlesData.length;

// Premium riddle count
export const getPremiumRiddleCount = (): number => riddlesData.filter(r => isPremiumLevel(r.id)).length;

export default riddlesData;
